// 反例组：篡改 payload / 篡改 header / 错误密钥 / 截断签名 —— 验签必须全部失败
const crypto = require('crypto');
const SECRET = Buffer.from('ch06-hs256-demo-secret');

function b64urlEncode(input) {
  const buf = Buffer.isBuffer(input) ? input : Buffer.from(String(input), 'utf8');
  return buf.toString('base64').replace(/=+$/g, '').replace(/\+/g, '-').replace(/\//g, '_');
}
function b64urlDecodeToBuffer(s) {
  const pad = s.length % 4 === 0 ? '' : '='.repeat(4 - (s.length % 4));
  return Buffer.from(s.replace(/-/g, '+').replace(/_/g, '/') + pad, 'base64');
}
function signHS256(secret, header, payload) {
  const h = b64urlEncode(JSON.stringify(header));
  const p = b64urlEncode(JSON.stringify(payload));
  const sig = crypto.createHmac('sha256', secret).update(h + '.' + p).digest();
  return h + '.' + p + '.' + b64urlEncode(sig);
}
function verifyHS256(secret, token) {
  const parts = token.split('.');
  if (parts.length !== 3) return false;
  const h = parts[0], p = parts[1], s = parts[2];
  const expected = crypto.createHmac('sha256', secret).update(h + '.' + p).digest();
  const got = b64urlDecodeToBuffer(s);
  return expected.length === got.length && crypto.timingSafeEqual(expected, got);
}

const good = signHS256(SECRET, { alg: 'HS256', typ: 'JWT' }, { sub: 'u1', role: 'user' });
const [h, p, s] = good.split('.');

console.log('baseline_ok=' + verifyHS256(SECRET, good));

// 篡改 payload：把 role 改成 admin，签名沿用原值
const evilPayload = b64urlEncode(JSON.stringify({ sub: 'u1', role: 'admin' }));
console.log('tampered_payload_ok=' + verifyHS256(SECRET, h + '.' + evilPayload + '.' + s));

// 篡改 header：把 typ 改掉
const evilHeader = b64urlEncode(JSON.stringify({ alg: 'HS256', typ: 'JWT2' }));
console.log('tampered_header_ok=' + verifyHS256(SECRET, evilHeader + '.' + p + '.' + s));

// 错误密钥
const other = signHS256(Buffer.from('other-secret'), { alg: 'HS256' }, { sub: 'u1', role: 'user' });
console.log('wrong_secret_ok=' + verifyHS256(SECRET, other));

// 截断签名（少一个字符）
const sigBuf = b64urlDecodeToBuffer(s);
const truncatedSig = b64urlEncode(sigBuf.subarray(0, sigBuf.length - 1));
console.log('truncated_signature_ok=' + verifyHS256(SECRET, h + '.' + p + '.' + truncatedSig));

// 结论：只要签名不是用同一密钥对「当前 header.payload」计算出来的，验签必然失败
console.log('all_forgeries_rejected=' + [
  verifyHS256(SECRET, h + '.' + evilPayload + '.' + s),
  verifyHS256(SECRET, evilHeader + '.' + p + '.' + s),
  verifyHS256(SECRET, other),
  verifyHS256(SECRET, h + '.' + p + '.' + truncatedSig),
].every(x => x === false));
